package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.JsonMappingException.InvalidFormatException;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.exc.InvalidFormatException;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.io.File;
import java.io.IOException;
import java.math.*;
import java.net.InetAddress;
import java.net.InetSocketAddress;
import java.net.URI;
import java.net.URL;
import java.nio.charset.Charset;
import java.util.*;
import java.util.Currency;
import java.util.Locale;
import java.util.TimeZone;
import java.util.regex.Pattern;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class Std__deserialize_TriageGen0Test {

    private DeserializationContext ctxt;
    private JsonParser parser;

    // Enum to match the internal _kind used in the source
    private enum Kind {
        STD_FILE, STD_URL, STD_URI, STD_CLASS, STD_JAVA_TYPE, STD_CURRENCY,
        STD_PATTERN, STD_LOCALE, STD_CHARSET, STD_TIME_ZONE, STD_INET_ADDRESS,
        STD_INET_SOCKET_ADDRESS
    }

    // Test subclass to expose protected constructor and method
    private static class TestStd extends FromStringDeserializer.Std {
        protected TestStd(Class<?> valueType, Kind kind) {
            super(valueType, kind.ordinal());
        }

        @Override
        public Object _deserialize(String value, DeserializationContext ctxt) throws IOException {
            return super._deserialize(value, ctxt);
        }
    }

    @Before
    public void setup() {
        ctxt = mock(DeserializationContext.class);
        parser = mock(JsonParser.class);
        when(ctxt.getParser()).thenReturn(parser);
    }

    @Test
    public void testFile() throws IOException {
        TestStd deserializer = new TestStd(File.class, Kind.STD_FILE);
        File expected = new File("test.txt");
        assertEquals(expected, deserializer._deserialize("test.txt", ctxt));
    }

    @Test
    public void testUrl() throws IOException {
        TestStd deserializer = new TestStd(URL.class, Kind.STD_URL);
        URL expected = new URL("http://google.com");
        assertEquals(expected, deserializer._deserialize("http://google.com", ctxt));
    }

    @Test
    public void testUri() throws IOException {
        TestStd deserializer = new TestStd(URI.class, Kind.STD_URI);
        URI expected = URI.create("http://google.com");
        assertEquals(expected, deserializer._deserialize("http://google.com", ctxt));
    }

    @Test
    public void testClassSuccess() throws IOException {
        TestStd deserializer = new TestStd(Object.class, Kind.STD_CLASS);
        when(ctxt.findClass("java.lang.String")).thenReturn(String.class);
        assertEquals(String.class, deserializer._deserialize("java.lang.String", ctxt));
    }

    @Test
    public void testClassFailure() throws IOException {
        TestStd deserializer = new TestStd(Object.class, Kind.STD_CLASS);
        when(ctxt.findClass(anyString())).thenThrow(new RuntimeException("Not found"));
        try {
            deserializer._deserialize("Unknown", ctxt);
        } catch (IOException e) {
            // Should be an instantiationException wrapped
        }
    }

    @Test
    public void testJavaType() throws IOException {
        TestStd deserializer = new TestStd(Object.class, Kind.STD_JAVA_TYPE);
        TypeFactory tf = TypeFactory.defaultInstance();
        when(ctxt.getTypeFactory()).thenReturn(tf);
        // constructFromCanonical for a simple type
        assertEquals(tf.constructFromCanonical("java.lang.String", null), 
                     deserializer._deserialize("java.lang.String", ctxt));
    }

    @Test
    public void testCurrency() throws IOException {
        TestStd deserializer = new TestStd(Currency.class, Kind.STD_CURRENCY);
        assertEquals(Currency.getInstance("USD"), deserializer._deserialize("USD", ctxt));
    }

    @Test
    public void testPattern() throws IOException {
        TestStd deserializer = new TestStd(Pattern.class, Kind.STD_PATTERN);
        assertEquals(Pattern.compile(".*"), deserializer._deserialize(".*", ctxt));
    }

    @Test
    public void testLocaleSingle() throws IOException {
        TestStd deserializer = new TestStd(Locale.class, Kind.STD_LOCALE);
        assertEquals(new Locale("en"), deserializer._deserialize("en", ctxt));
    }

    @Test
    public void testLocaleTwo() throws IOException {
        TestStd deserializer = new TestStd(Locale.class, Kind.STD_LOCALE);
        assertEquals(new Locale("en", "US"), deserializer._deserialize("en_US", ctxt));
    }

    @Test
    public void testLocaleThree() throws IOException {
        TestStd deserializer = new TestStd(Locale.class, Kind.STD_LOCALE);
        assertEquals(new Locale("zh", "CN", "UTF8"), deserializer._deserialize("zh_CN_UTF8", ctxt));
    }

    @Test
    public void testCharset() throws IOException {
        TestStd deserializer = new TestStd(Charset.class, Kind.STD_CHARSET);
        assertEquals(Charset.forName("UTF-8"), deserializer._deserialize("UTF-8", ctxt));
    }

    @Test
    public void testTimeZone() throws IOException {
        TestStd deserializer = new TestStd(TimeZone.class, Kind.STD_TIME_ZONE);
        assertEquals(TimeZone.getTimeZone("UTC"), deserializer._deserialize("UTC", ctxt));
    }

    @Test
    public void testInetAddress() throws IOException {
        TestStd deserializer = new TestStd(InetAddress.class, Kind.STD_INET_ADDRESS);
        assertEquals(InetAddress.getByName("127.0.0.1"), deserializer._deserialize("127.0.0.1", ctxt));
    }

    @Test
    public void testInetSocketAddressBracketedSuccess() throws IOException {
        TestStd deserializer = new TestStd(InetSocketAddress.class, Kind.STD_INET_SOCKET_ADDRESS);
        // IPv6 with port
        InetSocketAddress expected = new InetSocketAddress("[2001:db8::1]:8080", 8080);
        assertEquals(expected, deserializer._deserialize("[2001:db8::1]:8080", ctxt));

        // IPv6 without port
        InetSocketAddress expectedNoPort = new InetSocketAddress("[2001:db8::1]", 0);
        assertEquals(expectedNoPort, deserializer._deserialize("[2001:db8::1]", ctxt));
    }

    @Test
    public void testInetSocketAddressBracketedMissingClosing() {
        TestStd deserializer = new TestStd(InetSocketAddress.class, Kind.STD_INET_SOCKET_ADDRESS);
        try {
            deserializer._deserialize("[2001:db8::1", ctxt);
        } catch (InvalidFormatException e) {
            assertTrue(e.getMessage().contains("Bracketed IPv6 address must contain closing bracket"));
        } catch (IOException e) {
            throw new AssertionError("Expected InvalidFormatException", e);
        }
    }

    @Test
    public void testInetSocketAddressHostPort() throws IOException {
        TestStd deserializer = new TestStd(InetSocketAddress.class, Kind.STD_INET_SOCKET_ADDRESS);
        InetSocketAddress expected = new InetSocketAddress("localhost", 80);
        assertEquals(expected, deserializer._deserialize("localhost:80", ctxt));
    }

    @Test
    public void testInetSocketAddressHostOnly() throws IOException {
        TestStd deserializer = new TestStd(InetSocketAddress.class, Kind.STD_INET_SOCKET_ADDRESS);
        InetSocketAddress expected = new InetSocketAddress("127.0.0.1", 0);
        assertEquals(expected, deserializer._deserialize("127.0.0.1", ctxt));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testUnknownKind() throws IOException {
        // Use a kind that is not mapped in the switch (using a high value)
        // Since we can't easily inject an invalid enum via the constructor without trickery, 
        // we use a mock of the class if possible, or just rely on the fact that the switch handles specific cases.
        // However, the switch is on _kind. We can bypass via a fake subclass if needed.
        class BadStd extends FromStringDeserializer.Std {
            BadStd() { super(Object.class, 99); }
            @Override
            public Object _deserialize(String v, DeserializationContext c) throws IOException {
                return super._deserialize(v, c);
            }
        }
        new BadStd()._deserialize("val", ctxt);
    }
}
